import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.Locale;
import net.runelite.client.util.Filepath;

final class LocalExport {
    private final Gson json;

    LocalExport(Gson gson) {
        json = gson.newBuilder().serializeNulls().setPrettyPrinting().create();
    }

    private static String characterKey(String character) {
        String name = character.replace('\u00a0', ' ').strip();
        if (!name.matches("[A-Za-z0-9 _-]{1,12}")) {
            throw new IllegalArgumentException("Unexpected character name");
        }
        return name.toLowerCase(Locale.ROOT).replace('_', ' ').replace('-', ' ');
    }

    private static String snapshotKey(String character, JsonObject data) {
        String key = characterKey(character);
        if (!data.has("profile_mode")) return key;
        String mode = data.get("profile_mode").getAsString();
        if (!mode.matches("[A-Z_]{1,30}")) throw new IllegalArgumentException("Unexpected game mode");
        return mode.equals("STANDARD") ? key : key + "--" + mode.toLowerCase(Locale.ROOT);
    }

    Filepath write(Filepath root, String character, JsonObject data) throws IOException {
        return atomicWrite(root, "progress-" + snapshotKey(character, data) + ".json", json.toJson(data) + "\n");
    }

    Filepath writeDashboard(Filepath root, String character, JsonObject data) throws IOException {
        String key = snapshotKey(character, data);
        String template;
        try (InputStream resource = LocalExport.class.getResourceAsStream("/local-progress-dashboard.html")) {
            if (resource == null) throw new IOException("Dashboard template missing");
            template = new String(resource.readAllBytes(), StandardCharsets.UTF_8);
        }
        String prefix = "<script type=\"application/json\" id=\"embedded-data\">";
        String suffix = "</script>";
        String marker = prefix + "null" + suffix;
        int pos = template.indexOf(marker);
        if (pos < 0 || pos != template.lastIndexOf(marker)) throw new IOException("Invalid dashboard template");
        // Gson escapes HTML-sensitive characters by default. Also guarantee no literal '<'
        // in the payload so an imported string cannot close the inert script element.
        String payload = json.toJson(data).replace("<", "\\u003c");
        String html = template.substring(0, pos) + prefix + payload + suffix + template.substring(pos + marker.length());
        return atomicWrite(root, "dashboard-" + key + ".html", html);
    }

    private static Filepath atomicWrite(Filepath root, String filename, String body) throws IOException {
        root.createDirectories();
        Filepath target = root.joinSegment(filename);
        Filepath tmp = root.createTempFile(".progress-", ".tmp");
        try {
            tmp.write(body.getBytes(StandardCharsets.UTF_8));
            try {
                tmp.moveTo(target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
            } catch (AtomicMoveNotSupportedException ignored) {
                tmp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
            }
            return target;
        } finally {
            tmp.deleteIfExists();
        }
    }
}

