@PluginDescriptor(internalName = "local-progress-notes", name = "Local Progress Notes", description = "Save OSRS progress to your PC", tags = {"progress", "export", "quests"})
public final class LocalProgressPlugin extends Plugin {
    private static final String DATA_FOLDER = ".runelite/plugin-data/local-progress-notes";
    @Inject private Gson gson;
    private static final Pattern KILL_COUNT = Pattern.compile("Your (.{1,80}) kill count is: ([0-9,]{1,12})\\.");
    @Inject private Client client;
    @Inject private ConfigManager config;
    @Inject private ClientThread clientThread;
    @Inject private ClientToolbar toolbar;

    // All reads and updates of this map are confined to the client thread.
    private final Map<String, Map<String, Integer>> observed = new TreeMap<>();
    private final Map<String, Map<String, JsonObject>> seenCollection = new TreeMap<>();
    private final Map<String, CollectionCapture> allCollection = new TreeMap<>();
    private NavigationButton navigation;
    private CollectionCapture pendingCollection;
    private String pendingKey;
    private Runnable onCollectionFinished;
    private Runnable onCollectionAborted;

    @Override protected void startUp() {
        PluginPanel panel = new PluginPanel() { };
        panel.setLayout(new BorderLayout(0, 8));
        JButton export = new JButton("Export progress");
        JButton open = new JButton("Save dashboard");
        JButton full = new JButton("Capture full Collection Log");
        full.setToolTipText("Open your own in-game Collection Log first. No upload.");
        ExportStatus status = new ExportStatus();
        JButton[] buttons = {export, open, full};
        export.addActionListener(event -> begin(buttons, status, false));
        open.addActionListener(event -> begin(buttons, status, true));
        full.addActionListener(event -> {
            setButtons(buttons, false);
            status.setText("Reading Collection Log...");
            clientThread.invokeLater(() -> beginFullLog(buttons, status));
        });
        JPanel actions = new JPanel(new GridLayout(0, 1, 0, 6));
        actions.add(open);
        actions.add(export);
        actions.add(full);
        panel.add(actions, BorderLayout.NORTH);
        panel.add(status.panel, BorderLayout.CENTER);
        BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = icon.createGraphics();
        graphics.setColor(java.awt.Color.CYAN);
        graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 14));
        graphics.drawString("P", 3, 13);
        graphics.dispose();
        navigation = NavigationButton.builder().tooltip("Local Progress Notes").icon(icon).panel(panel).build();
        toolbar.addNavigation(navigation);
    }

    @Override protected void shutDown() {
        if (navigation != null) toolbar.removeNavigation(navigation);
        clientThread.invokeLater(this::resetPendingCollection);
    }

    private String currentCharacter() {
        if (client.getGameState() != GameState.LOGGED_IN) return null;
        Player self = client.getLocalPlayer();
        return self == null || self.getName() == null ? null : self.getName().replace('\u00a0', ' ').strip();
    }

    private String characterSessionKey(String name) {
        return name + ":" + client.getAccountHash() + ":" + RuneScapeProfileType.getCurrent(client);
    }

    private String ownLogKey() {
        String name = currentCharacter();
        if (name == null || name.isBlank() || client.getAccountHash() == -1L
            || RuneScapeProfileType.getCurrent(client) != RuneScapeProfileType.STANDARD
            || client.getVarbitValue(12061) != 0) return null;
        var log = client.getWidget(InterfaceID.Collection.INFINITY);
        return log != null && !log.isHidden() ? characterSessionKey(name) : null;
    }

    private void beginFullLog(JButton[] buttons, ExportStatus status) {
        String key = ownLogKey();
        var search = client.getWidget(InterfaceID.Collection.SEARCH_TOGGLE);
        if (key == null || search == null || search.isHidden()) {
            finish(buttons, status, "Open your own Collection Log first.", DATA_FOLDER);
            return;
        }
        var searchContents = client.getWidget(InterfaceID.Collection.SEARCH_RESULTS_CONTAINER);
        if (searchContents != null && !searchContents.isHidden()) {
            finish(buttons, status, "Exit Collection Log Search first.", "Click Back in the Collection Log, then try again.");
            return;
        }
        int count = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
        int total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
        pendingCollection = new CollectionCapture(total > 0 && count >= 0 && count <= total ? count : -1);
        pendingKey = key;
        onCollectionFinished = () -> capture(buttons, status, true, true);
        onCollectionAborted = () -> finish(buttons, status, "Collection capture didn’t finish.", "Open your own log, leave it open, and try again.");
        try {
            // The Plugin Hub documents this specific Collection Log Search action.
            // This touches only the local collection interface. Do not invoke WikiSync.
            client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
            client.runScript(CollectionCapture.SEARCH_SETUP);
        } catch (RuntimeException e) {
            abortCollection();
        }
    }

    @Subscribe public void onScriptPreFired(ScriptPreFired event) {
        if (pendingCollection == null || event.getScriptId() != CollectionCapture.ITEM_RESULT
            || event.getScriptEvent() == null || !pendingKey.equals(ownLogKey())) return;
        pendingCollection.observe(event.getScriptId(), event.getScriptEvent().getArguments());
    }

    @Subscribe public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() != GameState.LOGGED_IN && pendingCollection != null) abortCollection();
    }

    @Subscribe public void onGameTick(GameTick event) {
        if (pendingCollection == null) return;
        if (!pendingKey.equals(ownLogKey())) {
            abortCollection();
            return;
        }
        if (pendingCollection.advance()) {
            if (!pendingCollection.hasResult()) {
                abortCollection();
                return;
            }
            allCollection.put(pendingKey, pendingCollection);
            Runnable done = onCollectionFinished;
            resetPendingCollection();
            done.run();
        }
    }

    private void abortCollection() {
        Runnable aborted = onCollectionAborted;
        resetPendingCollection();
        if (aborted != null) aborted.run();
    }

    private void resetPendingCollection() {
        pendingCollection = null;
        pendingKey = null;
        onCollectionFinished = null;
        onCollectionAborted = null;
    }

    @Subscribe public void onScriptPostFired(net.runelite.api.events.ScriptPostFired event) {
        if (event.getScriptId() != net.runelite.api.ScriptID.COLLECTION_DRAW_LIST) return;
        String name = currentCharacter();
        if (name == null || name.isBlank() || client.getAccountHash() == -1L
            || RuneScapeProfileType.getCurrent(client) != RuneScapeProfileType.STANDARD) return;
        // Ignore the POH Adventure Log, which may display a different player's log.
        if (client.getVarbitValue(12061) != 0) return;
        var header = client.getWidget(net.runelite.api.gameval.InterfaceID.Collection.HEADER_TEXT);
        var contents = client.getWidget(net.runelite.api.gameval.InterfaceID.Collection.ITEMS_CONTENTS);
        if (header == null || contents == null || header.isHidden() || contents.isHidden()) return;
        var heading = header.getChild(0);
        var slots = contents.getDynamicChildren();
        if (heading == null || heading.getText() == null || slots == null || slots.length == 0) return;
        String title = Text.removeTags(heading.getText()).strip();
        if (title.isEmpty() || title.length() > 100) return;
        JsonObject page = new JsonObject();
        // Keep only positive observations. Empty/unknown widget slots are not missing proof.
        for (var item : slots) {
            if (item == null || item.getItemId() <= 0 || item.getOpacity() != 0 || item.getItemQuantity() <= 0) continue;
            int id = item.getItemId();
            var composition = client.getItemDefinition(id);
            if (composition != null) page.addProperty(Integer.toString(id), composition.getName());
        }
        if (page.size() > 0) {
            var cached = seenCollection.computeIfAbsent(characterSessionKey(name), key -> new TreeMap<>())
                .computeIfAbsent(title, key -> new JsonObject());
            page.entrySet().forEach(entry -> cached.add(entry.getKey(), entry.getValue()));
        }
    }

    @Subscribe public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE || event.getMessage() == null) return;
        Matcher match = KILL_COUNT.matcher(Text.removeTags(event.getMessage()));
        if (!match.matches()) return;
        String name = currentCharacter();
        if (name == null || name.isEmpty()) return;
        try {
            int count = Integer.parseInt(match.group(2).replace(",", ""));
            if (client.getAccountHash() != -1L) observed.computeIfAbsent(characterSessionKey(name), key -> new TreeMap<>()).put(match.group(1), count);
        } catch (NumberFormatException ignored) {
            // Ignore messages that are not clean lossless integer counts.
        }
    }

    private static void setButtons(JButton[] buttons, boolean enabled) {
        for (JButton button : buttons) button.setEnabled(enabled);
    }

    private void begin(JButton[] buttons, ExportStatus status, boolean showDashboard) {
        setButtons(buttons, false);
        status.setText("Reading progress...");
        clientThread.invokeLater(() -> capture(buttons, status, showDashboard, false));
    }

    private void capture(JButton[] buttons, ExportStatus status, boolean showDashboard, boolean openCollection) {
        String name = currentCharacter();
        if (name == null || name.isEmpty()) {
            finish(buttons, status, "Log into a game world first.", DATA_FOLDER);
            return;
        }

        final JsonObject result = new JsonObject();
        try {
            result.addProperty("schema_version", 1);
            if (openCollection) result.addProperty("collection_default_view", true);
            result.addProperty("character", name);
            result.addProperty("exported_at_utc", Instant.now().toString());
            result.addProperty("quest_points", client.getVarpValue(VarPlayerID.QP));

            JsonObject skills = new JsonObject();
            for (Skill skill : Skill.values()) {
                if ("OVERALL".equals(skill.name())) continue;
                JsonObject info = new JsonObject();
                info.addProperty("level", client.getRealSkillLevel(skill));
                info.addProperty("xp", client.getSkillExperience(skill));
                skills.add(skill.name(), info);
            }
            result.add("skills", skills);

            JsonObject quests = new JsonObject();
            for (Quest quest : Quest.values()) quests.addProperty(quest.getName(), quest.getState(client).name());
            result.add("quests", quests);
            result.add("diary_tiers_complete", GameProgress.buildDiaries(client));
            GameProgress.appendCombatAchievements(client, result);

            JsonObject counts = new JsonObject();
            observed.getOrDefault(characterSessionKey(name), Map.of()).forEach(counts::addProperty);
            BossProgress.append(client, config, result);
            JsonObject pages = new JsonObject();
            seenCollection.getOrDefault(characterSessionKey(name), Map.of()).forEach((page, items) -> pages.add(page, items.deepCopy()));
            result.add("collection_pages_seen", pages);
            CollectionCapture whole = allCollection.get(characterSessionKey(name));
            if (whole != null) {
                JsonObject collected = new JsonObject();
                whole.items().forEach((id, quantity) -> collected.addProperty(Integer.toString(id), quantity));
                result.add("collection_items_captured", collected);
                result.addProperty("collection_capture_expected", whole.expected());
            }
            if (RuneScapeProfileType.getCurrent(client) == RuneScapeProfileType.STANDARD) {
                int count = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
                int total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
                if (total > 0 && count >= 0 && count <= total) {
                    JsonObject completion = new JsonObject();
                    completion.addProperty("obtained", count);
                    completion.addProperty("total", total);
                    result.add("collection_progress", completion);
                }
            }
            result.add("kill_counts_seen_in_game_messages", counts);
            result.addProperty("kill_count_scope", "Game counters, active-profile kill-log cache, and session messages. Omitted counts are unknown.");
        } catch (RuntimeException e) {
            finish(buttons, status, "Couldn’t read progress. Try again.", e.getClass().getSimpleName());
            return;
        }

        // One small local write at a time; do not block the client thread.
        Thread writer = new Thread(() -> {
            try {
                Filepath directory = getPluginDirectory();
                LocalExport writerExport = new LocalExport(gson);
                Filepath file = writerExport.write(directory, name, result);
                if (!showDashboard) {
                    finish(buttons, status, "Progress JSON saved.", file.toString());
                    return;
                }
                try {
                    Filepath dashboard = writerExport.writeDashboard(directory, name, result);
                    finish(buttons, status, "Saved. Open the path below.", dashboard.toString());
                } catch (java.io.IOException | RuntimeException e) {
                    finish(buttons, status, "JSON saved; dashboard not saved.", file.toString());
                }
            } catch (java.io.IOException | RuntimeException e) {
                finish(buttons, status, "Couldn’t save export.", e.getClass().getSimpleName() + ": " + DATA_FOLDER);
            }
        }, "local-progress-export");
        writer.setDaemon(true);
        writer.start();
    }

    private static final class ExportStatus {
        final JPanel panel = new JPanel(new GridLayout(0, 1, 0, 4));
        final JLabel label = new JLabel("Local only. Nothing uploaded.");
        final JTextField detail = new JTextField(DATA_FOLDER, 1);

        ExportStatus() {
            detail.setEditable(false);
            detail.getAccessibleContext().setAccessibleName("Local export location or status details");
            detail.setToolTipText("Select and copy the path, then open it in your file manager.");
            panel.add(label);
            panel.add(detail);
        }

        void setText(String text) {
            label.setText(text);
        }

        void setDetail(String text) {
            detail.setText(text);
            detail.setCaretPosition(0);
        }
    }

    private static void finish(JButton[] buttons, ExportStatus status, String message, String detail) {
        SwingUtilities.invokeLater(() -> {
            status.setText(message);
            status.setDetail(detail);
            setButtons(buttons, true);
        });
    }
}

package com.localprogressnotes;

import java.util.Map;

public final class CollectionCaptureTest {
    private static void check(boolean ok) {
        if (!ok) throw new AssertionError("Collection capture regression");
    }

    public static void main(String[] args) {
        CollectionCapture c = new CollectionCapture(3);
        c.observe(0, new Object[]{0, 123, 99});
        c.observe(4100, new Object[]{4100, "bad", 10});
        c.observe(4100, new Object[]{4100, 4});
        c.observe(4100, null);
        c.observe(4100, new Object[]{4100, -1, 10});
        check(!c.hasResult());
        c.observe(4100, new Object[]{4100, 12922, 1});
        check(!c.advance());
        c.observe(4100, new Object[]{4100, 12922, 3});
        c.observe(4100, new Object[]{4100, 12922, 2});
        c.observe(4100, new Object[]{4100, 21907, 0});
        c.observe(4100, new Object[]{4100, 4201, 2});
        check(!c.advance() && c.advance());
        check(c.hasResult() && c.expected() == 3 && c.items().equals(Map.of(12922,3,21907,0,4201,2)));
        CollectionCapture empty = new CollectionCapture(0);
        check(empty.hasResult() && empty.items().isEmpty());
        CollectionCapture unknown = new CollectionCapture(-1);
        for (int i=0; i<5; i++) check(!unknown.advance());
        check(unknown.advance() && !unknown.hasResult());
        System.out.println("PASS: collection script arg validation, duplicate handling, quiet ticks, timeout and empty result");
    }
}

